insert into pw_player(player_no,user_id,nickname,real_name,gender,phone,introduction,audit_status,work_status,enabled,audit_remark,approved_at,rating_score,rating_count,order_count,max_active_orders,sort_no,remark,created_by,updated_by)
insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled)
insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled)
insert into pw_player_tag_rel(player_id,tag_id) select p.id,t.id from pw_player p join sys_user u on u.id=p.user_id cross join pw_player_tag t where u.username='admin' and t.tag_code in('aim-strong','good-command','patient') and not exists(select 1 from pw_player_tag_rel x where x.player_id=p.id and x.tag_id=t.id);
insert into pw_order(order_no,customer_id,assigned_player_id,order_status,total_amount,payable_amount,paid_amount,contact_name,contact_phone,customer_remark,paid_at,assigned_at,created_by)
insert into pw_order_item(order_id,product_id,sku_id,product_code,product_name,sku_code,sku_name,product_type,unit_price,quantity,subtotal_amount,service_snapshot)
insert into pw_order_game_profile(order_id,game_id,game_name,game_account,game_nickname,server_name,rank_name,extra_requirement) select o.id,g.id,g.game_name,'admin-demo-delta','演示客户A','烽火地带','钻石','安全撤离并讲解路线' from pw_order o join pw_game g on g.game_code='delta-force' where o.order_no='ORD-ADMIN-DEMO-ASSIGNED';
insert into pw_order_status_log(order_id,from_status,to_status,operator_id,reason) select o.id,'WAIT_ASSIGN','ASSIGNED',u.id,'V15 演示派单完成' from pw_order o join sys_user u on u.username='admin' where o.order_no='ORD-ADMIN-DEMO-ASSIGNED';
insert into pw_order(order_no,customer_id,assigned_player_id,order_status,total_amount,payable_amount,paid_amount,contact_name,contact_phone,customer_remark,paid_at,assigned_at,service_started_at,created_by)
insert into pw_order_item(order_id,product_id,sku_id,product_code,product_name,sku_code,sku_name,product_type,unit_price,quantity,subtotal_amount,service_snapshot)
insert into pw_order_game_profile(order_id,game_id,game_name,game_account,game_nickname,server_name,rank_name,extra_requirement) select o.id,g.id,g.game_name,'admin-demo-valorant','演示客户B','国服','钻石','主玩烟位，沟通教学' from pw_order o join pw_game g on g.game_code='valorant' where o.order_no='ORD-ADMIN-DEMO-SERVICE';
insert into pw_fulfillment(order_id,player_id,fulfillment_status) select o.id,o.assigned_player_id,'IN_SERVICE' from pw_order o where o.order_no='ORD-ADMIN-DEMO-SERVICE';
insert into pw_order_status_log(order_id,from_status,to_status,operator_id,reason) select o.id,'ASSIGNED','IN_SERVICE',u.id,'V15 演示开始服务' from pw_order o join sys_user u on u.username='admin' where o.order_no='ORD-ADMIN-DEMO-SERVICE';
insert into pw_order(order_no,customer_id,order_status,total_amount,payable_amount,paid_amount,contact_name,contact_phone,customer_remark,paid_at,created_by)
insert into pw_order_item(order_id,product_id,sku_id,product_code,product_name,sku_code,sku_name,product_type,unit_price,quantity,subtotal_amount,service_snapshot) select o.id,p.id,k.id,p.product_code,p.product_name,k.sku_code,k.sku_name,p.product_type,58,1,58,'[{"serviceName":"无畏契约排位陪玩","quantity":1,"unitType":"HOUR"}]' from pw_order o join pw_product p on p.product_code='valorant-ranked-hour' join pw_product_sku k on k.sku_code='valorant-ranked-1h' where o.order_no='ORD-ADMIN-DEMO-DISPATCH';
insert into pw_order_game_profile(order_id,game_id,game_name,game_account,game_nickname,server_name,rank_name,extra_requirement) select o.id,g.id,g.game_name,'dispatch-demo','演示客户C','国服','铂金','希望沟通积极' from pw_order o join pw_game g on g.game_code='valorant' where o.order_no='ORD-ADMIN-DEMO-DISPATCH';
insert into pw_dispatch_task(task_no,order_id,dispatch_mode,task_status,target_player_id,attempt_no,candidate_count,deadline_at,created_by) select 'DSP-ADMIN-DEMO',o.id,'DIRECT','DISPATCHING',p.id,1,1,timestamp '2099-12-31 23:59:59',u.id from pw_order o join sys_user u on u.username='admin' join pw_player p on p.user_id=u.id where o.order_no='ORD-ADMIN-DEMO-DISPATCH' and not exists(select 1 from pw_dispatch_task where task_no='DSP-ADMIN-DEMO');
insert into pw_dispatch_candidate(task_id,player_id,match_score,active_order_count,candidate_status,notified) select t.id,p.id,99,2,'PENDING',true from pw_dispatch_task t join sys_user u on u.username='admin' join pw_player p on p.user_id=u.id where t.task_no='DSP-ADMIN-DEMO';
insert into pw_dispatch_action_log(task_id,order_id,player_id,action_type,from_status,to_status,operator_id,reason) select t.id,t.order_id,t.target_player_id,'CREATE',null,'DISPATCHING',u.id,'V15 演示指定派单' from pw_dispatch_task t join sys_user u on u.username='admin' where t.task_no='DSP-ADMIN-DEMO';
