-- 为超级管理员准备可直接体验工作台的陪玩师身份；已有绑定时复用原档案。
select 'DEMO-ADMIN-PLAYER',u.id,'凌竞队长','平台管理员','UNKNOWN','19000000999','三角洲行动与无畏契约双游陪玩师，用于工作台和履约流程演示。','APPROVED','BUSY',true,'演示数据自动审核通过',current_timestamp,4.98,128,256,3,0,'V15 超级管理员演示陪玩师',u.id,u.id
from sys_user u where u.username='admin' and not exists(select 1 from pw_player p where p.user_id=u.id);
update pw_player set max_active_orders=3,audit_status='APPROVED',enabled=true where user_id=(select id from sys_user where username='admin');

select p.id,g.id,'LingJing-Delta','国服','烽火地带黑鹰',3,'熟悉烽火护航、撤离路线和全面战场指挥',true,'APPROVED',true from pw_player p join sys_user u on u.id=p.user_id cross join pw_game g where u.username='admin' and g.game_code='delta-force' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
select p.id,g.id,'LingJing-V','国服','神话',4,'主玩控场和先锋，支持排位与道具教学',false,'APPROVED',true from pw_player p join sys_user u on u.id=p.user_id cross join pw_game g where u.username='admin' and g.game_code='valorant' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);

-- 已接单：用于测试“开始服务”。
select 'ORD-ADMIN-DEMO-ASSIGNED',u.id,p.id,'ASSIGNED',99,99,99,u.nickname,u.phone,'演示：等待陪玩师开始服务',current_timestamp,current_timestamp,u.id from sys_user u join pw_player p on p.user_id=u.id where u.username='admin' and not exists(select 1 from pw_order where order_no='ORD-ADMIN-DEMO-ASSIGNED');
select o.id,p.id,k.id,p.product_code,p.product_name,k.sku_code,k.sku_name,p.product_type,99,1,99,'[{"serviceName":"烽火地带护航","quantity":1,"unitType":"GAME"}]' from pw_order o join pw_product p on p.product_code='delta-escort-experience' join pw_product_sku k on k.sku_code='delta-escort-1game' where o.order_no='ORD-ADMIN-DEMO-ASSIGNED';

-- 服务中：用于测试“提交完成凭证”。
select 'ORD-ADMIN-DEMO-SERVICE',u.id,p.id,'IN_SERVICE',116,116,116,u.nickname,u.phone,'演示：无畏契约排位服务中',current_timestamp,current_timestamp,current_timestamp,u.id from sys_user u join pw_player p on p.user_id=u.id where u.username='admin' and not exists(select 1 from pw_order where order_no='ORD-ADMIN-DEMO-SERVICE');
select o.id,p.id,k.id,p.product_code,p.product_name,k.sku_code,k.sku_name,p.product_type,58,2,116,'[{"serviceName":"无畏契约排位陪玩","quantity":2,"unitType":"HOUR"}]' from pw_order o join pw_product p on p.product_code='valorant-ranked-hour' join pw_product_sku k on k.sku_code='valorant-ranked-1h' where o.order_no='ORD-ADMIN-DEMO-SERVICE';

-- 待响应派单：用于测试接受或拒绝。
select 'ORD-ADMIN-DEMO-DISPATCH',u.id,'WAIT_ASSIGN',58,58,58,u.nickname,u.phone,'演示：待响应抢单任务',current_timestamp,u.id from sys_user u where u.username='admin' and not exists(select 1 from pw_order where order_no='ORD-ADMIN-DEMO-DISPATCH');
